#!/usr/bin/env node
// Generates quiz modules with literal translate() calls from the JSON
// sources in src/data/quiz/. Literal calls are required so that
// `docusaurus write-translations` extracts every string for Crowdin.
// questionCount and difficulty pass through so the JSON stays the single
// source of truth. Generated files are committed. check-quiz.js fails
// when they are out of sync.
const fs = require('fs');
const path = require('path');

const QUIZ_DIR = path.join(__dirname, '..', 'src', 'data', 'quiz');
const GEN_DIR = path.join(QUIZ_DIR, 'generated');

const t = (id, message) => `translate({id: ${JSON.stringify(id)}, message: ${JSON.stringify(message)}})`;

function renderModule(quiz) {
  const qid = quiz.id;
  const questions = quiz.questions
    .map((q) => {
      const options = q.options
        .map((opt, i) => `        ${t(`quiz.${qid}.${q.id}.option${i}`, opt)},`)
        .join('\n');
      return `    {
      id: ${JSON.stringify(q.id)},
      question: ${t(`quiz.${qid}.${q.id}.question`, q.question)},
      options: [
${options}
      ],
      correctAnswer: ${q.correctAnswer},
      explanation: ${t(`quiz.${qid}.${q.id}.explanation`, q.explanation)},
      sourceUrl: ${JSON.stringify(q.sourceUrl)},
    },`;
    })
    .join('\n');

  return `// AUTO-GENERATED by scripts/generate-quiz-modules.js from src/data/quiz/${qid}.json
// Do not edit by hand. Edit the JSON source and run: yarn build-quiz
import {translate} from '@docusaurus/Translate';

export function getQuizData() {
  return {
    id: ${JSON.stringify(qid)},
    title: ${t(`quiz.${qid}.title`, quiz.title)},
    description: ${t(`quiz.${qid}.description`, quiz.description)},
    questionCount: ${quiz.questionCount},
    difficulty: ${JSON.stringify(quiz.difficulty)},
    questions: [
${questions}
    ],
  };
}
`;
}

function main() {
  fs.mkdirSync(GEN_DIR, { recursive: true });
  const files = fs.readdirSync(QUIZ_DIR).filter((f) => f.endsWith('.json'));
  for (const file of files) {
    const quiz = JSON.parse(fs.readFileSync(path.join(QUIZ_DIR, file), 'utf8'));
    fs.writeFileSync(path.join(GEN_DIR, `${quiz.id}.js`), renderModule(quiz));
    console.log(`generated src/data/quiz/generated/${quiz.id}.js (${quiz.questions.length} questions)`);
  }
}

module.exports = { renderModule };
if (require.main === module) main();
